class TestTestSuiteIntegration:
    """Validate the test suite works as an integrated unit."""

    def test_all_test_files_have_test_functions(self, package_path: Path):
        """All test modules must contain test functions."""
        test_files = list(package_path.glob("test_*.py"))
        assert len(test_files) > 0, "No test files found"

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            assert "def test_" in content, (
                f"No test functions found in {test_file.name}"
            )

    def test_no_duplicate_test_names(self, package_path: Path):
        """Test function names must be unique across the suite."""
        test_names = set()
        test_files = list(package_path.glob("test_*.py"))

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            # Extract function names
            import ast
            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef) and node.name.startswith("test_"):
                    if node.name in test_names:
                        pytest.fail(f"Duplicate test name: {node.name}")
                    test_names.add(node.name)

    def test_test_files_have_proper_imports(self, package_path: Path):
        """Test files must import pytest."""
        test_files = list(package_path.glob("test_*.py"))

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            assert "import pytest" in content, (
                f"Missing 'import pytest' in {test_file.name}"
            )

    def test_fixtures_are_defined(self, package_path: Path):
        """Test suite must have fixture definitions."""
        test_files = list(package_path.glob("test_*.py"))
        fixture_count = 0

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            fixture_count += content.count("@pytest.fixture")

        assert fixture_count > 0, "No fixtures defined in test suite"


