class TestTestSuiteReliability:
    """Validate test suite reliability characteristics."""

    def test_tests_are_deterministic(self, package_path: Path):
        """Tests must not use random values without seeding."""
        test_files = list(package_path.glob("test_*.py"))

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            if "random" in content and "random.seed" not in content:
                pytest.warn(f"Random usage without seeding in {test_file.name}")

    def test_no_hardcoded_paths(self, package_path: Path):
        """Tests must not use hardcoded absolute paths."""
        test_files = list(package_path.glob("test_*.py"))

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            # Check for Windows-style paths
            if re.search(r'[A-Z]:\\', content):
                pytest.fail(f"Hardcoded Windows path in {test_file.name}")
            # Check for Unix-style absolute paths
            if re.search(r'/(?:home|usr|var|etc|opt)/', content):
                pytest.fail(f"Hardcoded Unix path in {test_file.name}")

    def test_tests_are_isolated(self, package_path: Path):
        """Tests must not modify global state."""
        test_files = list(package_path.glob("test_*.py"))

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            # Check for global variable modification
            if re.search(r'^[A-Z_]+\s*=', content, re.MULTILINE):
                pytest.warn(f"Potential global state modification in {test_file.name}")


