def _get_test_function_count(package_path: Path) -> int:
    """Count total test functions in the suite."""
    import ast
    total = 0
    test_files = list(package_path.glob("test_*.py"))

    for test_file in test_files:
        content = test_file.read_text(encoding="utf-8")
        tree = ast.parse(content)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and node.name.startswith("test_"):
                total += 1

    return total


def _get_fixture_count(package_path: Path) -> int:
    """Count total fixtures in the suite."""
    total = 0
    test_files = list(package_path.glob("test_*.py"))

    for test_file in test_files:
        content = test_file.read_text(encoding="utf-8")
        total += content.count("@pytest.fixture")

    return total


