class TestTestSuiteSummary:
    """Provide summary metrics for the test suite."""

    def test_suite_has_minimum_tests(self, package_path: Path):
        """Test suite must have a minimum number of tests."""
        test_count = _get_test_function_count(package_path)
        assert test_count >= 10, (
            f"Test suite has only {test_count} tests, minimum 10 required"
        )

    def test_suite_has_minimum_fixtures(self, package_path: Path):
        """Test suite must have a minimum number of fixtures."""
        fixture_count = _get_fixture_count(package_path)
        assert fixture_count >= 3, (
            f"Test suite has only {fixture_count} fixtures, minimum 3 required"
        )

    def test_suite_has_test_categories(self, package_path: Path):
        """Test suite must have categorized tests."""
        test_files = list(package_path.glob("test_*.py"))
        categories = set()

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            if "class Test" in content:
                # Extract class names
                import ast
                tree = ast.parse(content)
                for node in ast.walk(tree):
                    if isinstance(node, ast.ClassDef) and node.name.startswith("Test"):
                        categories.add(node.name)

        assert len(categories) >= 3, (
            f"Test suite has only {len(categories)} categories, minimum 3 required"
        )


